package dev.soundceiling.app;

final class ControlDecision {
    enum Mode{DBFS,SPL} enum Action{HOLD,DECREASE,RAISE,CAP,ERROR} enum SafetyReason{NONE,AUDIBLE_FLOOR,MAXIMUM_CAP}
    final long atMs;final Mode mode;final float sourceRmsDb,sourcePeakDb;final boolean signalPresent,allowAutoMute;final int currentIndex;final float currentControlGainDb,target,ceiling;final int capPercent,capIndex;final float desiredGainDb;final int rawDesiredIndex,protectedDesiredIndex;final boolean peakViolation;final Action action;final SafetyReason safetyReason;final String reason;final int requestedIndex,appliedIndex;
    ControlDecision(long atMs,Mode mode,float sourceRmsDb,float sourcePeakDb,boolean signalPresent,boolean allowAutoMute,int currentIndex,float currentControlGainDb,float target,float ceiling,int capPercent,int capIndex,float desiredGainDb,int rawDesiredIndex,int protectedDesiredIndex,boolean peakViolation,Action action,SafetyReason safetyReason,String reason,int requestedIndex,int appliedIndex){this.atMs=atMs;this.mode=mode;this.sourceRmsDb=sourceRmsDb;this.sourcePeakDb=sourcePeakDb;this.signalPresent=signalPresent;this.allowAutoMute=allowAutoMute;this.currentIndex=currentIndex;this.currentControlGainDb=currentControlGainDb;this.target=target;this.ceiling=ceiling;this.capPercent=capPercent;this.capIndex=capIndex;this.desiredGainDb=desiredGainDb;this.rawDesiredIndex=rawDesiredIndex;this.protectedDesiredIndex=protectedDesiredIndex;this.peakViolation=peakViolation;this.action=action;this.safetyReason=safetyReason;this.reason=reason;this.requestedIndex=requestedIndex;this.appliedIndex=appliedIndex;}
    ControlDecision withAppliedIndex(int value){return new ControlDecision(atMs,mode,sourceRmsDb,sourcePeakDb,signalPresent,allowAutoMute,currentIndex,currentControlGainDb,target,ceiling,capPercent,capIndex,desiredGainDb,rawDesiredIndex,protectedDesiredIndex,peakViolation,action,safetyReason,reason,requestedIndex,value);}
}
